import {useMemo} from 'react';
import {Text, useThemeType} from '@gravity-ui/uikit';
import Yagr from '@gravity-ui/yagr/react';
import type {MinimalValidConfig, RawSerieData} from '@gravity-ui/yagr';

import '@gravity-ui/yagr/index.css';

const HOURS = 24;
const SECONDS_PER_HOUR = 60 * 60;
const SAMPLE_INTERVAL_MS = 1000;
const DATA_POINTS = HOURS * SECONDS_PER_HOUR + 1;

function getComputedColor(name: string): string | undefined {
  if (typeof window === 'undefined') {
    return undefined;
  }

  const value = window.getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  return value || undefined;
}

function buildInitialData(): {
  timeline: number[];
  series: RawSerieData[];
} {
  const now = Date.now();
  const timeline = new Array<number>(DATA_POINTS);
  const data = new Array<number>(DATA_POINTS);

  for (let index = 0; index < DATA_POINTS; index += 1) {
    timeline[index] = now - (DATA_POINTS - 1 - index) * SAMPLE_INTERVAL_MS;
    data[index] = 0;
  }

  return {
    timeline,
    series: [
      {
        id: 'cpu',
        name: 'CPU',
        type: 'line',
        data,
      },
    ],
  };
}

function makePoint(timestamp: number, value: number) {
  return {timestamp, value};
}

export function CpuLoadChart() {
  const themeType = useThemeType();

  const {timeline: initialTimeline, series: initialSeries} = useMemo(buildInitialData, []);

  const config = useMemo<MinimalValidConfig>(() => {
    return {
      timeline: initialTimeline,
      series: initialSeries,
      chart: {
        size: {
          adaptive: true,
          height: 320,
        },
        timeMultiplier: 1,
        appearance: {
          theme: themeType,
          locale: 'ru',
        },
      },
      series: undefined,
      axes: {
        x: {
          precision: 0,
        },
        y: {
          precision: 0,
        },
      },
      scales: {
        y: {
          min: 0,
          max: 100,
        },
      },
      cursor: {
        snapToValues: false,
      },
    } as MinimalValidConfig;
  }, [themeType, initialTimeline, initialSeries]);

  return (
    <div className=\"cpu-load-chart\">
      <div className=\"cpu-load-chart__header\">
        <Text variant=\"subheader-2\" color=\"secondary\">
          Загрузка CPU
        </Text>
        <Text variant=\"caption-2\" color=\"hint\">
          за последние сутки
        </Text>
      </div>
